(function() {
    'use strict';

    class RestaurantAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Restaurant P&L: From Menu to Margin';
            this.version = '1.1.0';

            this.MONTHS = [
                {
                    title: 'Month 1 — Diagnosis and Quick Wins',
                    description: 'Welcome to <strong>Bistro Meridiano</strong>, a 60-seat full-service restaurant. The previous manager left a prime cost of 69% and a net margin of just 2.1%. The owner wants prime cost below 63% and net margin above 6% by Month 4.<br><br>This month, focus on <strong>quick wins</strong>: waste reduction, schedule optimization, and supplier review. Your baseline: Revenue $95,000 | Food Cost 34% | Labor Cost 35% | Reputation 3.8/5.0 | 3,120 monthly covers.'
                },
                {
                    title: 'Month 2 — Menu Redesign and Pricing',
                    description: 'Time to apply <strong>Menu Engineering</strong>. Your 48-item menu has been analyzed using the Kasavana-Smith matrix. You have Stars (high CM, high popularity), Plowhorses (low CM, high popularity), Puzzles (high CM, low popularity), and Dogs (low CM, low popularity).<br><br>Focus on <strong>removing Dogs, repricing Plowhorses, promoting Puzzles</strong>, and investing in your beverage program for higher margins.'
                },
                {
                    title: 'Month 3 — Revenue Growth and Reputation',
                    description: 'Operations are stabilizing. Now drive <strong>revenue growth</strong> through table management, marketing, and online reputation.<br><br>Remember: RevPASH = Revenue / (Seats x Hours Open). You can increase it by raising average check, improving table turns, or filling more seats. But aggressive table turns may hurt guest experience and your reputation score.'
                },
                {
                    title: 'Month 4 — Integration and Sustainability',
                    description: 'Final month. <strong>Lock in your improvements</strong> and build systems for long-term sustainability. Invest in staff development, operational technology, and strategic positioning.<br><br>Target check: Prime Cost below 63% and Net Profit Margin above 6%. Your reputation score must be maintained or improved versus baseline 3.8.'
                }
            ];

            this.EVENTS = [
                [
                    { text: 'Walk-in refrigerator failed Thursday evening before a busy weekend. Emergency repair cost $2,800. Food spoilage losses of $1,200 in perishable inventory.', revenueDelta: 0, costDelta: 4000, reputationDelta: 0 },
                    { text: 'Health inspector visit: minor violation for improper storage temperatures. Corrective action cost $600. No public impact but staff morale dipped slightly.', revenueDelta: 0, costDelta: 600, reputationDelta: -0.05 },
                    { text: 'A key prep cook called in sick on Saturday, the busiest day. You paid overtime to cover the shift, adding $900 in extra labor cost.', revenueDelta: 0, costDelta: 900, reputationDelta: 0 }
                ],
                [
                    { text: 'A popular food blogger posted a positive review video that went viral. Demand spiked 25% for two weeks, straining kitchen capacity but boosting revenue.', revenueDelta: 8000, costDelta: 2500, reputationDelta: 0.15 },
                    { text: 'A competitor opened one block away with a 20% discount promotion. You lost some price-sensitive guests this month.', revenueDelta: -5000, costDelta: 0, reputationDelta: -0.05 },
                    { text: 'Key protein supplier announced a 15% price increase due to supply chain disruptions. Your food cost is directly affected this month.', revenueDelta: 0, costDelta: 3200, reputationDelta: 0 }
                ],
                [
                    { text: 'Local street festival two blocks away brought a 40% walk-in traffic increase over the weekend, but parking issues generated some complaints.', revenueDelta: 6000, costDelta: 1800, reputationDelta: 0.05 },
                    { text: 'A social media complaint about slow service went viral (120 shares). Some guests cancelled reservations this week.', revenueDelta: -3500, costDelta: 0, reputationDelta: -0.2 },
                    { text: 'Heavy rainfall reduced covers by 30% for two consecutive weeks. Revenue dropped but perishable inventory spoiled due to over-purchasing.', revenueDelta: -7000, costDelta: 1500, reputationDelta: 0 }
                ],
                [
                    { text: 'A high-performing server received a competing offer from a new restaurant. Counter-offer cost $400/month raise to retain them.', revenueDelta: 0, costDelta: 400, reputationDelta: 0.05 },
                    { text: 'A private dining event booking for 30 guests brought excellent revenue and social media exposure for the restaurant.', revenueDelta: 4500, costDelta: 1200, reputationDelta: 0.1 },
                    { text: 'POS system glitch caused order mix-ups during a busy Friday dinner service. Several tables received wrong dishes; comps issued.', revenueDelta: -1500, costDelta: 800, reputationDelta: -0.1 }
                ]
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    revenue: 95000,
                    foodCostPct: 34.0,
                    laborCostPct: 35.0,
                    primeCostPct: 69.0,
                    netMarginPct: 2.1,
                    reputationScore: 3.8,
                    covers: 3120,
                    avgCheck: 22.00,
                    revPASH: 12.50,
                    wasteVariance: 4.8,
                    bevRevenuePct: 22,
                    netProfit: 1995,
                    cumulativeProfit: 0,
                    staffCount: 18,
                    revenueHistory: [],
                    primeCostHistory: [],
                    netMarginHistory: [],
                    reputationHistory: [],
                    profitHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    menuStrategy: 0,
                    staffCount: 18,
                    wasteControl: 0,
                    beverageInvestment: 0,
                    marketingPct: 1.5,
                    tableTurnTarget: 120,
                    reviewStrategy: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);

            var menuEl = document.getElementById('menuStrategyInput');
            if (menuEl) decisions.menuStrategy = parseInt(menuEl.value);

            var staffEl = document.getElementById('staffCountInput');
            if (staffEl) decisions.staffCount = parseInt(staffEl.value);

            var wasteEl = document.getElementById('wasteControlInput');
            if (wasteEl) decisions.wasteControl = parseInt(wasteEl.value);

            var bevEl = document.getElementById('beverageInput');
            if (bevEl) decisions.beverageInvestment = parseInt(bevEl.value);

            var mktEl = document.getElementById('marketingInput');
            if (mktEl) decisions.marketingPct = parseFloat(mktEl.value);

            var turnEl = document.getElementById('tableTurnInput');
            if (turnEl) decisions.tableTurnTarget = parseInt(turnEl.value);

            var revEl = document.getElementById('reviewStrategyInput');
            if (revEl) decisions.reviewStrategy = parseInt(revEl.value);

            if (!decisions.staffCount || decisions.staffCount < 14 || decisions.staffCount > 22) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('staff_warning'), 'warning'
                );
                return false;
            }

            if (decisions.marketingPct < 0 || decisions.marketingPct > 6) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('marketing_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var baseRevenue = ds.revenue;
            var baseFoodCostPct = ds.foodCostPct;
            var baseLaborCostPct = ds.laborCostPct;
            var baseReputation = ds.reputationScore;
            var baseCovers = ds.covers;
            var baseAvgCheck = ds.avgCheck;
            var baseWasteVar = ds.wasteVariance;
            var baseBevPct = ds.bevRevenuePct;

            var foodCostDelta = 0;
            var laborCostDelta = 0;
            var revenueDelta = 0;
            var reputationDelta = 0;
            var coversDelta = 0;
            var avgCheckDelta = 0;
            var wasteVarDelta = 0;
            var bevPctDelta = 0;
            var investmentCosts = 0;

            if (d.menuStrategy === 1) {
                foodCostDelta -= 1.5;
                avgCheckDelta += 1.2;
                reputationDelta -= 0.05;
            } else if (d.menuStrategy === 2) {
                foodCostDelta -= 0.8;
                avgCheckDelta += 2.5;
                coversDelta -= Math.round(baseCovers * 0.04);
                reputationDelta -= 0.08;
            } else if (d.menuStrategy === 3) {
                foodCostDelta -= 2.2;
                avgCheckDelta += 3.0;
                coversDelta -= Math.round(baseCovers * 0.02);
                investmentCosts += 2000;
                reputationDelta += 0.05;
            }

            var staffDiff = d.staffCount - ds.staffCount;
            var laborPerStaff = baseLaborCostPct / ds.staffCount;
            laborCostDelta += staffDiff * laborPerStaff;

            var serverRatio = d.staffCount / 60;
            if (serverRatio < 0.27) {
                reputationDelta -= 0.15;
                coversDelta -= Math.round(baseCovers * 0.05);
            } else if (serverRatio < 0.30) {
                reputationDelta -= 0.08;
            } else if (serverRatio > 0.33) {
                reputationDelta += 0.05;
            }

            if (d.wasteControl === 1) {
                wasteVarDelta -= 1.2;
                foodCostDelta -= 0.8;
                investmentCosts += 1500;
            } else if (d.wasteControl === 2) {
                wasteVarDelta -= 2.5;
                foodCostDelta -= 1.8;
                investmentCosts += 3500;
            }

            if (d.beverageInvestment === 1) {
                bevPctDelta += 3;
                avgCheckDelta += 1.5;
                investmentCosts += 800;
            } else if (d.beverageInvestment === 2) {
                bevPctDelta += 7;
                avgCheckDelta += 3.5;
                investmentCosts += 2500;
                foodCostDelta -= 0.5;
            }

            var marketingSpend = d.marketingPct / 100;
            if (d.marketingPct >= 2 && d.marketingPct <= 4) {
                coversDelta += Math.round(baseCovers * (d.marketingPct * 0.025));
                reputationDelta += 0.05;
            } else if (d.marketingPct > 4) {
                coversDelta += Math.round(baseCovers * (d.marketingPct * 0.02));
                reputationDelta += 0.08;
            } else if (d.marketingPct > 0) {
                coversDelta += Math.round(baseCovers * (d.marketingPct * 0.015));
            }

            if (d.tableTurnTarget === 105) {
                coversDelta += Math.round(baseCovers * 0.08);
                avgCheckDelta -= 0.8;
                reputationDelta -= 0.03;
            } else if (d.tableTurnTarget === 90) {
                coversDelta += Math.round(baseCovers * 0.18);
                avgCheckDelta -= 2.0;
                reputationDelta -= 0.12;
            }

            if (d.reviewStrategy === 1) {
                reputationDelta += 0.08;
                investmentCosts += 300;
            } else if (d.reviewStrategy === 2) {
                reputationDelta += 0.12;
                investmentCosts += 800;
            } else {
                reputationDelta -= 0.03;
            }

            var eventIdx = Math.min(period - 1, this.EVENTS.length - 1);
            var monthEvents = this.EVENTS[eventIdx];
            var event = monthEvents[Math.floor(Math.random() * monthEvents.length)];

            revenueDelta += event.revenueDelta;
            investmentCosts += event.costDelta;
            reputationDelta += event.reputationDelta;

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (eventPanel && eventText) {
                eventPanel.style.display = 'block';
                eventText.innerHTML = event.text;
            }

            var reputationEffect = (baseReputation - 3.8) * 0.03;
            coversDelta += Math.round(baseCovers * reputationEffect);

            var newCovers = Math.max(2000, baseCovers + coversDelta);
            var newAvgCheck = Math.max(15, baseAvgCheck + avgCheckDelta);
            var newRevenue = Math.round(newCovers * newAvgCheck);
            newRevenue += revenueDelta;
            newRevenue = Math.max(50000, newRevenue);

            var newFoodCostPct = Math.max(22, Math.min(42, baseFoodCostPct + foodCostDelta));
            var newLaborCostPct = Math.max(24, Math.min(42, baseLaborCostPct + laborCostDelta));
            var newPrimeCostPct = Math.round((newFoodCostPct + newLaborCostPct) * 10) / 10;

            var marketingCost = newRevenue * marketingSpend;
            var controllableExpPct = 5 + marketingSpend * 100;
            var fixedOverheadPct = 12;
            var totalCostPct = newPrimeCostPct + controllableExpPct + fixedOverheadPct;
            var newNetMarginPct = Math.round((100 - totalCostPct) * 10) / 10;

            var newNetProfit = Math.round(newRevenue * (newNetMarginPct / 100)) - investmentCosts;
            newNetMarginPct = Math.round((newNetProfit / newRevenue) * 1000) / 10;

            var newReputation = Math.round(Math.max(2.5, Math.min(5.0, baseReputation + reputationDelta)) * 100) / 100;

            var seats = 60;
            var hoursOpen = 7.5;
            var daysOpen = 26;
            var dinnerRevShare = 0.65;
            var dinnerHours = 4;
            var newRevPASH = Math.round((newRevenue * dinnerRevShare / (seats * dinnerHours * daysOpen)) * 100) / 100;

            var newWasteVar = Math.max(0.5, Math.min(8, baseWasteVar + wasteVarDelta));
            var newBevPct = Math.max(18, Math.min(45, baseBevPct + bevPctDelta));

            ds.revenue = newRevenue;
            ds.foodCostPct = Math.round(newFoodCostPct * 10) / 10;
            ds.laborCostPct = Math.round(newLaborCostPct * 10) / 10;
            ds.primeCostPct = newPrimeCostPct;
            ds.netMarginPct = newNetMarginPct;
            ds.reputationScore = newReputation;
            ds.covers = newCovers;
            ds.avgCheck = Math.round(newAvgCheck * 100) / 100;
            ds.revPASH = newRevPASH;
            ds.wasteVariance = Math.round(newWasteVar * 10) / 10;
            ds.bevRevenuePct = Math.round(newBevPct);
            ds.netProfit = newNetProfit;
            ds.cumulativeProfit += newNetProfit;
            ds.staffCount = d.staffCount;

            ds.revenueHistory.push(newRevenue);
            ds.primeCostHistory.push(newPrimeCostPct);
            ds.netMarginHistory.push(newNetMarginPct);
            ds.reputationHistory.push(newReputation);
            ds.profitHistory.push(newNetProfit);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);

            return {
                period: period,
                revenue: newRevenue,
                foodCostPct: ds.foodCostPct,
                laborCostPct: ds.laborCostPct,
                primeCostPct: newPrimeCostPct,
                netMarginPct: newNetMarginPct,
                netProfit: newNetProfit,
                reputationScore: newReputation,
                covers: newCovers,
                avgCheck: ds.avgCheck,
                revPASH: newRevPASH,
                wasteVariance: ds.wasteVariance,
                bevRevenuePct: ds.bevRevenuePct,
                event: event.text
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('revenueDisplay', 'domainState.revenue',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('primeCostDisplay', 'domainState.primeCostPct',
                (v) => v.toFixed(1) + '%');
            uiManager.bind('netMarginDisplay', 'domainState.netMarginPct',
                (v) => v.toFixed(1) + '%');
            uiManager.bind('reputationDisplay', 'domainState.reputationScore',
                (v) => v.toFixed(2) + ' / 5.0');
            uiManager.bind('coversDisplay', 'domainState.covers',
                (v) => Math.round(v).toLocaleString());
            uiManager.bind('avgCheckDisplay', 'domainState.avgCheck',
                (v) => '$' + v.toFixed(2));
            uiManager.bind('foodCostDisplay', 'domainState.foodCostPct',
                (v) => v.toFixed(1) + '%');
            uiManager.bind('laborCostDisplay', 'domainState.laborCostPct',
                (v) => v.toFixed(1) + '%');
            uiManager.bind('revpashDisplay', 'domainState.revPASH',
                (v) => '$' + v.toFixed(2));
            uiManager.bind('wasteVarianceDisplay', 'domainState.wasteVariance',
                (v) => v.toFixed(1) + '%');
            uiManager.bind('bevRevenueDisplay', 'domainState.bevRevenuePct',
                (v) => v + '%');
            uiManager.bind('netProfitDisplay', 'domainState.netProfit',
                (v) => '$' + Math.round(v).toLocaleString());
        }

        getChartConfig() {
            return {
                profitChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Net Profit ($)',
                            data: [],
                            backgroundColor: 'rgba(76,175,80,0.6)',
                            borderColor: '#4CAF50',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Monthly Net Profit' } },
                        scales: { y: { beginAtZero: true } }
                    }
                },
                primeCostChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Prime Cost %',
                            data: [],
                            borderColor: '#E53935',
                            backgroundColor: 'rgba(229,57,53,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2
                        }, {
                            label: 'Target (63%)',
                            data: [],
                            borderColor: '#43A047',
                            borderWidth: 2,
                            borderDash: [8, 4],
                            fill: false,
                            pointRadius: 0
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Prime Cost % vs Target' } },
                        scales: { y: { min: 50, max: 75 } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.profitHistory.map(function(_, i) { return 'M' + (i + 1); });
            var targetLine = labels.map(function() { return 63; });
            return {
                profitChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.profitHistory }]
                },
                primeCostChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.primeCostHistory },
                        { data: targetLine }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};

            var lastResult = history[history.length - 1].results || {};
            var primeCost = lastResult.primeCostPct || 69;
            var netMargin = lastResult.netMarginPct || 2.1;
            var reputation = lastResult.reputationScore || 3.8;

            var profits = history.map(function(r) { return r.results ? r.results.netProfit || 0 : 0; });
            var cumulativeProfit = profits.reduce(function(s, p) { return s + p; }, 0);

            var financialScore = 0;
            if (primeCost <= 63) financialScore += 20;
            else if (primeCost <= 66) financialScore += 12;
            else if (primeCost <= 69) financialScore += 5;

            if (netMargin >= 6) financialScore += 20;
            else if (netMargin >= 4) financialScore += 12;
            else if (netMargin >= 2) financialScore += 5;

            if (cumulativeProfit > 30000) financialScore += 10;
            else if (cumulativeProfit > 15000) financialScore += 6;
            else if (cumulativeProfit > 0) financialScore += 3;

            var operationalScore = 0;
            var foodCost = lastResult.foodCostPct || 34;
            if (foodCost <= 30) operationalScore += 10;
            else if (foodCost <= 33) operationalScore += 6;

            var revPASH = lastResult.revPASH || 12.5;
            if (revPASH >= 18) operationalScore += 10;
            else if (revPASH >= 15) operationalScore += 6;

            var wasteVar = lastResult.wasteVariance || 4.8;
            if (wasteVar <= 2) operationalScore += 10;
            else if (wasteVar <= 3.5) operationalScore += 6;

            var guestScore = 0;
            if (reputation >= 4.2) guestScore += 10;
            else if (reputation >= 4.0) guestScore += 6;

            var avgCheck = lastResult.avgCheck || 22;
            if (avgCheck >= 28) guestScore += 5;
            else if (avgCheck >= 25) guestScore += 3;

            var covers = lastResult.covers || 3120;
            if (covers >= 3800) guestScore += 5;
            else if (covers >= 3400) guestScore += 3;

            var totalScore = financialScore + operationalScore + guestScore;

            var performance = 'Needs Improvement';
            if (totalScore >= 75) performance = 'Exceptional GM';
            else if (totalScore >= 60) performance = 'Strong Performance';
            else if (totalScore >= 45) performance = 'Competent Management';
            else if (totalScore >= 30) performance = 'Developing Skills';

            var insights = [];

            if (primeCost <= 63) {
                insights.push('Prime cost target achieved! Excellent cost management.');
            } else {
                insights.push('Prime cost target missed. Review food cost and labor scheduling for savings.');
            }

            if (netMargin >= 6) {
                insights.push('Net margin target met. The restaurant is sustainably profitable.');
            } else {
                insights.push('Net margin below target. Consider revenue growth strategies alongside cost control.');
            }

            if (reputation < 3.8) {
                insights.push('Reputation declined from baseline. Cost cutting may have hurt service quality.');
            } else if (reputation >= 4.2) {
                insights.push('Strong reputation growth. Guest experience investments are paying off.');
            }

            if (wasteVar <= 2) {
                insights.push('Waste variance under control. Theoretical and actual food costs are well aligned.');
            }

            return {
                totalScore: totalScore,
                financialScore: financialScore,
                operationalScore: operationalScore,
                guestScore: guestScore,
                performance: performance,
                primeCostFinal: primeCost,
                netMarginFinal: netMargin,
                reputationFinal: reputation,
                cumulativeProfit: cumulativeProfit,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.primeCostPct > 68) return window.mySimulation.t('hint_high_prime');
            if (results.primeCostPct > 63 && results.primeCostPct <= 68) return window.mySimulation.t('hint_moderate_prime');
            if (results.netMarginPct < 0) return window.mySimulation.t('hint_loss');
            if (results.reputationScore < 3.5) return window.mySimulation.t('hint_reputation');
            if (results.wasteVariance > 4) return window.mySimulation.t('hint_waste');
            if (results.bevRevenuePct < 25) return window.mySimulation.t('hint_beverage');
            if (results.primeCostPct <= 63 && results.netMarginPct >= 6) return window.mySimulation.t('hint_excellent');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.revenue',         label: 'Revenue',        i18nKey: 'col_revenue',     formatter: (v) => '$' + Math.round(v).toLocaleString() },
                { key: 'results.primeCostPct',     label: 'Prime Cost %',   i18nKey: 'col_prime_cost',  formatter: (v) => v.toFixed(1) + '%' },
                { key: 'results.netMarginPct',     label: 'Net Margin %',   i18nKey: 'col_net_margin',  formatter: (v) => v.toFixed(1) + '%' },
                { key: 'results.netProfit',        label: 'Net Profit',     i18nKey: 'col_net_profit',  formatter: (v) => '$' + Math.round(v).toLocaleString() },
                { key: 'results.reputationScore',  label: 'Reputation',     i18nKey: 'col_reputation',  formatter: (v) => v.toFixed(2) },
                { key: 'results.covers',           label: 'Covers',         i18nKey: 'col_covers' },
                { key: 'results.avgCheck',         label: 'Avg Check',      i18nKey: 'col_avg_check',   formatter: (v) => '$' + v.toFixed(2) }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:              `Restaurant P&L: From Menu to Margin`,
                    subtitle:           `Bistro Meridiano Management Challenge`,
                    month_label:        `Month`,
                    period_of:          `of`,
                    briefing_title:     `Monthly Briefing`,
                    revenue_label:      `Monthly Revenue`,
                    prime_cost_label:   `Prime Cost %`,
                    net_margin_label:   `Net Profit Margin`,
                    reputation_label:   `Reputation Score`,
                    covers_label:       `Monthly Covers`,
                    avg_check_label:    `Average Check`,
                    decisions_heading:  `Monthly Decisions`,
                    menu_strategy_label: `Menu Strategy`,
                    menu_opt_maintain:  `Maintain current menu`,
                    menu_opt_engineer:  `Menu engineering: remove Dogs, promote Stars`,
                    menu_opt_reprice:   `Aggressive repricing of Plowhorses (+8-12%)`,
                    menu_opt_redesign:  `Full redesign: engineering + menu psychology`,
                    staff_label:        `Total Staff Count (14-22)`,
                    waste_label:        `Waste Control Investment`,
                    waste_opt_none:     `No investment`,
                    waste_opt_basic:    `Basic: portion control + FIFO ($1,500)`,
                    waste_opt_full:     `Comprehensive: portions + FIFO + par reset + theft prevention ($3,500)`,
                    beverage_label:     `Beverage Program Investment`,
                    bev_opt_none:       `Maintain current program`,
                    bev_opt_moderate:   `Train staff on suggestive selling ($800)`,
                    bev_opt_major:      `Cocktail program + wine list upgrade ($2,500)`,
                    marketing_label:    `Marketing Budget (% of Revenue, 0-6)`,
                    table_turn_label:   `Table Turn Target (minutes per seating)`,
                    turn_opt_120:       `120 min - Relaxed dining`,
                    turn_opt_105:       `105 min - Standard pace`,
                    turn_opt_90:        `90 min - Quick turnover`,
                    review_label:       `Online Review Response Strategy`,
                    review_opt_minimal: `Minimal: generic auto-responses`,
                    review_opt_selective: `Selective: personalized replies to negative reviews`,
                    review_opt_active:  `Active: respond personally to every review`,
                    submit_btn:         `Submit Month`,
                    undo_btn:           `Undo Last Month`,
                    event_title:        `Random Event`,
                    pnl_heading:        `P&L Summary`,
                    food_cost_pct:      `Food Cost %`,
